INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Massacre', 'Larry''s Christmas tree has been telling him to kill. But whose side is the tree really on? And can he trust what he''s hearing? CHRISTMAS MASSACRE is an 80''s inspired stealth slasher game with low-poly, PS1-style graphics. Sneak, stalk and murder your prey without being caught. You must kill without being seen to complete each level.' FROM games WHERE igdb_id = 186281 ON CONFLICT (game_id, language_code) DO NOTHING;
