INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Kouryuudou: Unconnected Marketeers', 'Touhou Kouryuudou: Unconnected Marketeers is the eighteenth official installment of the Touhou Project. It was announced by ZUN on the Touhou Project news blog Touhou Yomoyama News, February 2021. A playable demo is scheduled for release on March 21st the same year, at Reitaisai 18, and the full version is scheduled to be released in May.' FROM games WHERE igdb_id = 144093 ON CONFLICT (game_id, language_code) DO NOTHING;
