INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skyland-rush-air-raid-attack', 145963, '2021-04-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aso.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arav1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skyland Rush: Air Raid Attack', 'A shooting rush game against creatures of the dark! Shoot and fly through the sky of Skylandia in an epic adventure. How far can you get? Dash into the world and challenge your skills in this side-scrolling game! Features: - Shoot as many creatures as possible to increase your score - Use powerful charms to upgrade your weapons - Beware of puzzling traps in your skyway - Explore action-packed game blocks of elevating difficulty - Complete challenging missions and claim the rewards - Brace yourself, Guardians may toughen your journey - Collect egglings to unlock "Awakening" and to meet the Titans Evil has taken over Skylandia! Zenya needs your help! Survive the sneaky attacks of various bugsters, ominous witches, robobirds, little devils and other notorious monsters that will threaten your mission! Shoot''em up to clear your way and claim the rewards. A long journey lies ahead, dark times shall not prevail! Tap and balance though dense vegetation, blocking rocks and dangerous caves! Collect powerful charms to wipe out all the enemy creatures with your super weapons. Avoid or smash the obstacles and spot the hidden traps ahead so that you can disable them in time. During your epic adventures, different types of egglings will come across your path! Each one of them is an ill-omen of an evil presence! Collect them all while monstrous Titans await to be awakened! Join Zenya''s journey to the adventurous Skylandia!' FROM games WHERE igdb_id = 145963 ON CONFLICT (game_id, language_code) DO NOTHING;
