INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faircroft''s Antiques: Treasures of Treffenburg Collector''s Edition', 'Join Antiquities expert Mia Faircroft as she visits the beautiful Austrian town of Treffenburg in search of a fabled antique collection that once belonged to a famous matriarch named Lady Ophelia Harcourt. But Mia knows there’s a story behind every antique, and when she finds that some details aren’t adding up, she’ll dig through every nook and cranny to uncover the Harcourt family’s secrets. Join Mia in this lavishly illustrated Hidden-Object Puzzle Adventure game bursting with mystery, a diverse cast of lovable characters, and mind-bending minigames in every chapter!' FROM games WHERE igdb_id = 147753 ON CONFLICT (game_id, language_code) DO NOTHING;
