INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astralis', 'Priviet to Astralis ! In this short game, you play as Lieutenant Alekseï Ivanov, a soldier awaken from his cryo-sleep to face a terrible threat happening in the soviet spaceship "Astralis" lost in an unkown part of the universe. Astralis is FPS horror sci-fi game with retro graphics and sounds.' FROM games WHERE igdb_id = 156019 ON CONFLICT (game_id, language_code) DO NOTHING;
