INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gamemory', 'Improve memory of kids under 5 years old with Augmented Reality. This game is for 2 people — one of the parents and little wunderkind. The adult opens every square and lets the kid remember it. After that, closes and asks the kid what kind of thing under the exact square. Well, in the end, open together to check.' FROM games WHERE igdb_id = 158961 ON CONFLICT (game_id, language_code) DO NOTHING;
