INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('riddle-of-the-sphinx--1', 174286, '2021-06-21', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riddle of the Sphinx', 'Explore secret chambers. Discover hidden tombs. Unearth ancient riddles. And unravel an ancient riddle, entombed for centuries by the ancient Egyptians! Riddle of the Sphinx is an epic ancient Egyptian adventure featuring unlimited exploration in and around the Giza Sphinx and Great Pyramid of Cheops. This is your opportunity to immerse yourself into the Giza Sphinx and Great Pyramid - one of the last seven wonders of the ancient world.Download Riddle of the Sphinx to explore and discover the mysteries of Ancient Egypt!' FROM games WHERE igdb_id = 174286 ON CONFLICT (game_id, language_code) DO NOTHING;
