INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanji Swipe: Sliding Puzzle', 'Kanji Swipe: Sliding Puzzle is a simple sliding puzzle and the best way to learn how to write Kanji, one of the 3 writing systems used in the Japanese language. Are you struggling to remember what all the Kanji look like or how they are written? Learn them naturally as you play! Not interested in learning Kanji? Not a problem! The fun challenge of creating all these funny looking characters will keep you glued to your screen.' FROM games WHERE igdb_id = 174293 ON CONFLICT (game_id, language_code) DO NOTHING;
