INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PrincessCliffhouse', 'princess simulation game. 프린세스 시뮬레이션 육성게임입니다. 플레이어는 4주씩 10달 총, 40턴 동안의 시간이 주어지며 그 안에 스탯을 올려 다양한 엔딩을 보는 것이 목표입니다. 수업, 아르바이트, 던전탐험, 한달에 한 번 있는 마을로의 외출, 메인 시나리오 및 서브 시나리오 옷 갈아입히기 등의 컨텐츠를 즐길 수 있습니다.' FROM games WHERE igdb_id = 170082 ON CONFLICT (game_id, language_code) DO NOTHING;
