INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('murdered-by-midnight', 174241, '2021-09-26', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murdered by Midnight', 'The Murdered by Midnight board game can now be enjoyed anywhere on the go. Either play with friends or anyone around the world. Be the first to deduce the murderer, murder weapon, motive and time of death to solve the murder and win the game! Not including the detectives, there are 25 people at the manor during the time of the murder, this includes staff, family members and friends. Considering that the person who found the body is not the murderer, there are 22 possible suspects for the crime. With all of the combinations of people, weapons, motives and times, there are more than 483,000 possible outcomes just waiting to be explored!' FROM games WHERE igdb_id = 174241 ON CONFLICT (game_id, language_code) DO NOTHING;
