INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'From Shadows', 'From Shadows is an action game blending the style of fast-paced platformers and beat’em ups. The menacing gothic atmosphere and foreboding music build tension, while the hand-drawn graphics give shape to unimaginable horrors straight from hell. This indie title offers options for solo play as well as cooperative split-screen and lets you publish your scores on global leaderboards. Unleash your inner beast and step out of the shadows!' FROM games WHERE igdb_id = 147675 ON CONFLICT (game_id, language_code) DO NOTHING;
