INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'End Matter', 'End Matter is a hyper-stylized real time space battle simulator created by your friendly, buzzword-abusing indie dev next door who''s really happy that you''re considering investing your hard earned money into funding his horrible, horrible coffee addiction. But hey, that''ll at least guarantee you an evening of fun on the couch kicking some aliens in the behind while wondering whether it was really necessary to blend a casual strategy game with a fricking dating sim. It''s just that one level tho, promised. Well, anyways...INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 175265 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
