INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandstorm!', 'You are Josué Jorge and you have time-traveled to the ancient world of Egypt in search of the Crowns of Power. They are hidden inside the labyrinthine and macabre Great Pyramids and guarded by powerful deities. Now, our hero must face unexpected dangers such as giant spiders, poisonous snakes, and, if that’s not enough, time itself because if the countdown reaches zero, he will be forever stuck in the past….' FROM games WHERE igdb_id = 260866 ON CONFLICT (game_id, language_code) DO NOTHING;
