INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipe Fitter', 'Pipe fitter is the best brain-teaser for every pipeline puzzle lover. If you are a big fan of pipe connection puzzle, do not miss this great pipeline puzzle game! Everyone can enjoy the fun of plumbing and connecting the right pipes in the right orientation! An amusing, inspiring pipe puzzle experience . All pipe plumbing fans, get ready for your exciting pipe plumbing puzzle journey in over 250 levels! Features : - 250 Levels - Different difficulties - Hint function' FROM games WHERE igdb_id = 172549 ON CONFLICT (game_id, language_code) DO NOTHING;
