INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Flight Simulator', 'Take flight in real airplanes across this massively detailed open-world flight simulator. Explore high resolution sceneries. Take off, fly and land successfully back to airport. This very complete flight simulator will allow you to fliy on modern fighter like Fairchild Republic A-10 Thunderbolt II as well as tourist airplane, like Embraer EMB 314 Super Tucano. Enjoy the joy of flying while listening to ''Pix Arts Pro Flight Simulator'' playlist on the leading music streaming service.' FROM games WHERE igdb_id = 176146 ON CONFLICT (game_id, language_code) DO NOTHING;
