INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghosts-and-apples', 180963, '2021-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57p2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar199m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghosts and Apples', 'You have come to a house full of magic where intrigue and mystery reign. A ghost spies through the window while an octopus acts as a coat hanger. A raven is guarding the evil potion brewing cauldron. And, in the distance, a vampire is about to awaken… Your soul has been trapped within the puppet Jack. Wander around and unravel the mysteries of the ancient inhabitants of the House of Frantic Pictures. Beware, though, strange pictures will suck you into a haunted world. Catch the ghosts and turn them into tasty apples. Put your skills to the test and get hooked by a unique gameplay that combines action, strategy, reasoning and memory. Accumulate golden apples and gems to buy the keys of every room within the mysterious house. Over 150 handcrafted levels designed to thrill. Play with Jack and Shelly and enjoy two distinct gameplay styles. Dozens of trophies to win. Unlocking them will test your skills and wit. Find secret rooms that only the best may access. Customizable local multiplayer will provide you and your friends with exciting challenges. Immerse yourself in a fabulous and detailed world where in every corner you will discover extraordinary creatures. Enjoy the evocative hand-drawn art style. Animated for an adventure full of wonder and magic. The compelling soundtrack and original sound effects bring the game world alive and real. A help mode for color-blind people is available.' FROM games WHERE igdb_id = 180963 ON CONFLICT (game_id, language_code) DO NOTHING;
