INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Rabbit', 'You find yourself in a futuristic dystopian city. You get the idea: Dark smog. A rogue A.I. Corporate drones. Actual drones. The whole enchilada. In this fast-paced 2D platformer, you play as Arisu, a Runner tasked to deliver the ambiguous Blue Rabbit "packages" around the city.' FROM games WHERE igdb_id = 149975 ON CONFLICT (game_id, language_code) DO NOTHING;
