INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Majustsushi Rintiara', 'Rintiara der Lanserge, a sorceress of the Royal Knights, has been fighting against the Rebellion, an organization that does evil all over the world. This time, her mission is to defeat the leaders of the Rebellion in the small country of Ethia. Will she be able to accomplish her mission‼?' FROM games WHERE igdb_id = 174123 ON CONFLICT (game_id, language_code) DO NOTHING;
