INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gallagher Case', 'One night in 1982 a teenager comes home from school. He receives a call from Mrs Gallagher, his neighbour, an invalid woman with Alzheimer''s disease. She can''t turn on the TV, she''s not very good with technology, so she convinces the young man to help her with the television, not knowing that he was about to live the worst experience of his life.' FROM games WHERE igdb_id = 213843 ON CONFLICT (game_id, language_code) DO NOTHING;
