INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweet Sugar Candy', 'Explore a beautiful world full of candy. Develop your skills in an hundred of well-designed levels, while collecting and using power-ups wisely. Match and crush three or more of the same candies to complete levels, using special candies where possible! You''ll find more fun in this game than in any other Match game! Collect virtual currency throughout the levels (no extra purchase required, you play to win) and try your luck at the Wheel of Fortune. Sweet Sugar Candy will bring you many hours of fun!' FROM games WHERE igdb_id = 152428 ON CONFLICT (game_id, language_code) DO NOTHING;
