INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('secret-agent-game-the-5-keys', 175559, '2021-09-17', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Agent Game: The 5 Keys', 'Secret Agent Game: The 5 Keys is a point and click adventure game unlike anything you have ever played before. Why? Because of this simple concept. “Why do so many game developers try to make computer games look like ‘real life’ when you can make ‘real life’ play like a computer game? “ The result is a masterpiece that has the charm of the classic point and click adventure games with the realism of being in a movie. It''s Interactive video but it''s taken to a whole new exciting level of interactions. CG Entertainment brings together skillsets from movie making, 3d animation and coding to create an immersive interactive world.' FROM games WHERE igdb_id = 175559 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 175559 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
