INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Siebenstreich', '"Siebenstreich" is a hand-drawn 2D adventure for pop culture lovers about an unlikely hero and sustainability in times of magic. Set in a troubled fantasy kingdom, this game follows a tailor and his loyal sidekick Trudie, a vegan carnivorous plant, on their curious road trip to save the day. A 21st century fairy tale filled with pop culture references, addressing ethical topics in an entertaining way.' FROM games WHERE igdb_id = 121822 ON CONFLICT (game_id, language_code) DO NOTHING;
