INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiwi', 'Kiwi is a three level auto-scroller that focuses on the endless adventure during which the player must help maneuver the bird in order to dodge environmental obstacles whilst trying to not get killed by enemies! The powerup store gives the player an opportunity to utilize the coins collected throughout the game as well as a greater chance to get higher scores on the leaderboard. Players can also get information regarding the featured endangered species they will encounter throughout the game!' FROM games WHERE igdb_id = 186256 ON CONFLICT (game_id, language_code) DO NOTHING;
