INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmo''s Quickstop', '"Welcome to the fast-paced world of interstellar gas station management! As the new owner and operator of Cosmo’s Quickstop, your skills in customer service and multitasking will be your keys to success. Keep your establishment equipped with the finest amenities for customers on the go, including hot coffee showers, diamond deluxe shipwashes, and sparkling clean glorp rooms! With hard work and a bit of luck, you’ll be well on your way to owning the most popular attraction along Route 66 Million!"' FROM games WHERE igdb_id = 54676 ON CONFLICT (game_id, language_code) DO NOTHING;
