INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Checkers Master', 'Checkers Master is a checkers game with American/English official rules. Your goal: capture all your opponent''s pieces. This game supports both 1 player and 2 player gameplay, so you can play against friends or test your skills against a challenging computer opponent. Intuitive touch controls make it easy to play checkers on your device - just tap a piece and then tap where you want it to go.' FROM games WHERE igdb_id = 147775 ON CONFLICT (game_id, language_code) DO NOTHING;
