INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbocorns', 'The official Rainbocorns coloring-in game and Webisodes! Rainbocorns comes with 50 re-usable digital coloring-in pages which you can color-in using either your finger or a stylus. You can also zoom in, out and move the image around to get the perfect colored in picture and you can save and share your pictures by using the capture button on the left Joy-Con. As a bonus we have included all the series one webisodes into the game, so now you can watch all eight webisodes, anytime, anywhere.' FROM games WHERE igdb_id = 147722 ON CONFLICT (game_id, language_code) DO NOTHING;
