INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('knights-of-san-francisco', 174204, '2021-05-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9str.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdzsv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of San Francisco', 'Explore what remains of the ancient city of San Francisco and experience dynamic combat in this RPG text game. What if goblins, ogres, and dragons weren''t imagined? What if our ancestors were, unwittingly, foretelling the future? Find yourself in that future, centuries from now, among the ruins of what was once the 21st century – where these terrifying creatures roam freely… Heavily inspired by modern tabletop RPGs, this game puts you in the shoes of a young necromancer on a quest. Battle monsters, raise the dead, and explore what remains of the ancient city of San Francisco.' FROM games WHERE igdb_id = 174204 ON CONFLICT (game_id, language_code) DO NOTHING;
