INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papercraft', 'A paper world of survival awaits your fingertips. In this 2.5D landscape, craft your chosen tools and weaponry to build your base, mine, chop trees, fish, hunt, cook, farm or, draw your blade to crumple your foes! Manage resources like health, happiness, hunger, water and time with care to survive. But be warned, the challenges of the wild are not as paper-thin as you might think in this pleasant land.' FROM games WHERE igdb_id = 51647 ON CONFLICT (game_id, language_code) DO NOTHING;
