INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Pieces: Valentine''s Day', 'The puzzles in this special Valentine Edition are all about love. Choose from a great amount of romantic puzzles in HD-quality and adjust the way you would like to play to your own preference. You get to decide for yourself how many pieces your puzzle may contain. Do you dare to make a puzzle with 1000 puzzles pieces or do you prefer a puzzle with a little less pieces? In this uplifting game your personal puzzle fun is central!' FROM games WHERE igdb_id = 145365 ON CONFLICT (game_id, language_code) DO NOTHING;
