INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('escape-from-a-deserted-island-the-adventures-of-nyanzou-and-kumakichi', 154979, '2021-07-15', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/arvgu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape From a Deserted Island: The Adventures of Nyanzou & Kumakichi', 'One day, while Kumakichi is worried over what to eat for dinner, Nyanzou pauses from reading his manga to announce, “I''m gonna be the King of the Pirates.” Hearing what only could be a joke, Kumakichi thinks, “Not again…”. He tries to ignore Nyanzou, but Nyanzou has a reputation for being reckless. He forces Kumakichi to come along out to sea. And as expected, Nyanzou＆Kumakichi get shipwrecked right after heading out. They drift ashore onto a deserted island. Help these two escape. It''s your standard escape game, on the easy side, and highly recommended for beginners. It comes with autosave, hints, and memo functions.' FROM games WHERE igdb_id = 154979 ON CONFLICT (game_id, language_code) DO NOTHING;
