INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Volleyball Challenge', 'Activate SUPERPOWERS – in this sports game you can add fireballs, vanishing balls, superspeed, blocks, and many others to your arsenal – play now and discover them for yourself! Develop your player''s SKILLS – raise your stats across categories such as serve power and strength, stamina, or attack! You will have a bundle of additional outfits to choose from as well as bags with super contents to open – as long as you win matches! Make your opponents tremble at the sight of your player! Volleyball will never be the same – play Volleyball Challenge and be part of the sports revolution!' FROM games WHERE igdb_id = 163694 ON CONFLICT (game_id, language_code) DO NOTHING;
