INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You First', 'You First is a romance visual novel in which you follow the evolution of the characters throughout three episodes in different years of their lives. A quirky narrator who makes fun of the events will guide you, and you will be able to choose how their love story unfolds at specific times in each episode. Will they dare to tell the truth or a white lie? Will they have sex at home or make plans outside? Interactive decisions in a romantic style suited for singles, couples and dating sim lovers as well.' FROM games WHERE igdb_id = 210367 ON CONFLICT (game_id, language_code) DO NOTHING;
