INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Construction Site Driver', 'You may know about driving, but that doesn''t mean you''re ready for what awaits you at the site. Begin your adventure today and discover the unique joys of being a construction worker! Take control of one of ten distinct and varied vehicles that share one characteristic - every one of them is essential in completing the building. Drive a cement mixer, a drilling truck, a fork lift, an excavator and more! Feel the immense power of those impressive vehicles and use them to the best of your ability!' FROM games WHERE igdb_id = 186578 ON CONFLICT (game_id, language_code) DO NOTHING;
