INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternal Cave Escape', 'Eternal Cave Escape is a precision-platformer that challenges players to climb their way out of a cave using a pickaxe. Mistakes in this cave cost the player time rather than lives, as all progress can be lost through falling. Will you rise out of this seemingly endless cave, or will you be stuck here forever?' FROM games WHERE igdb_id = 163122 ON CONFLICT (game_id, language_code) DO NOTHING;
