INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantom Detective', '高一下半学期，和同学们一起乘大巴去春游的我，不幸卷入了一场离奇的车祸，住院治疗了整整两年才得以康复。 本以为大难不死必有后福，却没想到这只是一连串离奇事件的开端…… 同时配合简单易上手的自定义剧情编辑器，把你自己的的故事，在不同的平台，告诉给不同的人听。' FROM games WHERE igdb_id = 127503 ON CONFLICT (game_id, language_code) DO NOTHING;
