INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vacation Adventures: Park Ranger 4', 'Join the newly promoted ranger in another truly sensational Vacation Adventure in the great outdoors. Enjoy this outstanding collection of Hidden Object scenes and puzzles set in an idyllic national park. As well as finding Hidden Objects around the park you will need to perform your duties as a park ranger. Protect the environment by collecting all the bonus trash items to recycle and catalogue all the wildlife throughout the park in your wildlife Journal.' FROM games WHERE igdb_id = 88460 ON CONFLICT (game_id, language_code) DO NOTHING;
