INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('faerie-alchemy-puzzle-game', 174246, '2021-06-19', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faerie Alchemy: Puzzle Game', 'Transmute magical elements to combine them into rarified forms. Faerie Alchemy is a more than a match-3 puzzle game. It is simple to understand with deep complexity to master as you aim for higher heights of elements and score. To play Faerie Alchemy, the player drops two elemental pieces at a time into the game board. As three or more elements combine, the elemental pieces group together to form an elemental piece of the next highest quality at the lowest left area of the game board where the original group occupied. The strategy is in dropping pieces in ways which ensure cascades into higher and higher elemental tiers.' FROM games WHERE igdb_id = 174246 ON CONFLICT (game_id, language_code) DO NOTHING;
