INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singing Iris', '《鸢之歌》是一款涵盖末日元素的养成类视觉小说游戏，讲述了一名感染者与一名人造天才科学家以及一名背叛人类的少女之间发生的故事；在这个时代什么是正确的事情？拯救世界？亦或者不惜代价的活下去？我们都将在一次又一次的选择里见证这一切。' FROM games WHERE igdb_id = 156756 ON CONFLICT (game_id, language_code) DO NOTHING;
