INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Four in a Row', 'This is not only a well-known “four in a row game”. The new game - all sides edition is distinguished by the possibility of placing chips on the board from each of the 4 sides! Its purpose is to place 4 tokens next to each other (horizontally, vertically or diagonally) which requires strategy and tactical thinking from you. Connect 4 chips in a row and win! Key features of connect 4 in Four in a row: - Classic board games with new rules - Develop your brain and relax - Play against AI - Beautiful and simple user interface' FROM games WHERE igdb_id = 146688 ON CONFLICT (game_id, language_code) DO NOTHING;
