INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flocks', 174193, '2021-06-01', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flocks', 'Flocks is not just another puzzler. It''s a world of never-ending, simple and beautiful "scenarios". You will need to think outside the box in each one of them. But it won''t be tedious, we promise: they are physics based, they are fast, they are really fun, and there are many of them. Instead of controlling a single character, you will be handling groups (Flocks), combining and splitting them to solve every challenge you face. Grab objects, move them, pile them... Anything you can think of! The beautiful design is intended to create the illusion of being a simple two-dimensional illustration, while allowing you to enjoy a real three-dimensional realm that you wouldn''t expect. Have fun!' FROM games WHERE igdb_id = 174193 ON CONFLICT (game_id, language_code) DO NOTHING;
